def fibonacci_index(n):
    if n == 0:
        return 0
    a, b = 0, 1
    idx = 1
    while b < n:
        a, b = b, a + b
        idx += 1
    return idx if b == n else -1

def is_isogram(s):
    letters = [ch.lower() for ch in s if ch.isalpha()]
    return len(letters) == len(set(letters))

