def count_transitions(sequence):
    d = {}
    for i in range(len(sequence) - 1):
        key = f"{sequence[i]}->{sequence[i + 1]}"
        d[key] = d.get(key, 0) + 1
    return d

def zigzag_check(lst):
    n = len(lst)
    if n < 2:
        return True
    diffs = [lst[i + 1] - lst[i] for i in range(n - 1)]
    if any(d == 0 for d in diffs):
        return False
    for i in range(1, len(diffs)):
        if (diffs[i] > 0) == (diffs[i - 1] > 0):
            return False
    return True

def remove_duplicate_adjacent_chars(s):
    if not s:
        return ""
    result = [s[0]]
    for c in s[1:]:
        if c != result[-1]:
            result.append(c)
    return "".join(result)

def is_valid_file_name(s, allowed_exts):
    if s.count('.') != 1:
        return False
    name, ext = s.split('.')
    if not name or not all(c.isalnum() or c in '_-' for c in name):
        return False
    return ext in allowed_exts and ext == ext.lower()

def time_from_am_pm_string(time_str):
    time_part, period = time_str.split(' ')
    h, m = time_part.split(':')
    h = int(h) % 12
    if period == 'PM':
        h += 12
    return h*60 + int(m)

